 * The policy a claim reports against, named by the quote that wrote it. A claim
 * can only be held against business that actually put a policy on the books.
 */
function policyWrittenBy(policies: Map<number, Policy>, index: number): Policy {
  const policy = policies.get(index);
  if (policy === undefined) {
    throw new Error(`step ${index} did not write a policy`);
  }
  return policy;
}

